import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;
public class PluginReferenceGraph{
 static Set<String> rs;static void type(String s){if(s==null)return;while(s.startsWith("["))s=s.substring(1);if(s.startsWith("L"))rs.add(s);}
 static void ref(Reference r){if(r instanceof TypeReference)type(((TypeReference)r).getType());else if(r instanceof FieldReference){FieldReference f=(FieldReference)r;type(f.getDefiningClass());type(f.getType());}else if(r instanceof MethodReference){MethodReference m=(MethodReference)r;type(m.getDefiningClass());type(m.getReturnType());for(CharSequence p:m.getParameterTypes())type(p.toString());}else if(r instanceof MethodProtoReference){MethodProtoReference m=(MethodProtoReference)r;type(m.getReturnType());for(CharSequence p:m.getParameterTypes())type(p.toString());}}
 public static void main(String[] a)throws Exception{var z=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(28));for(String n:z.getDexEntryNames())for(ClassDef c:z.getEntry(n).getDexFile().getClasses()){rs=new TreeSet<>();type(c.getSuperclass());for(String s:c.getInterfaces())type(s);for(Field f:c.getFields())type(f.getType());boolean hilt=false;for(Method m:c.getMethods()){if(m.getName().equals("generatedComponent"))hilt=true;type(m.getReturnType());for(CharSequence p:m.getParameterTypes())type(p.toString());if(m.getImplementation()!=null){for(Instruction i:m.getImplementation().getInstructions()){if(i instanceof ReferenceInstruction)ref(((ReferenceInstruction)i).getReference());if(i instanceof DualReferenceInstruction)ref(((DualReferenceInstruction)i).getReference2());}for(TryBlock<? extends ExceptionHandler> t:m.getImplementation().getTryBlocks())for(ExceptionHandler h:t.getExceptionHandlers())type(h.getExceptionType());}}rs.remove(c.getType());System.out.println(c.getType()+"\t"+(hilt?"HILT":"CLASS")+"\t"+String.join(",",rs));}}
}
